;border-radius:8px;overflow:hidden;background:#ddd}.n503-category-grid img{width:100%;height:100%;object-fit:cover;filter:brightness(.76)}.n503-category-grid b{position:absolute;left:12px;bottom:16px;color:#fff;font-size:20px}.n503-product-grid{display:grid;gap:10px}.n503-four{grid-template-columns:repeat(4,1fr)}.n503-five{grid-template-columns:repeat(5,1fr)}.n503-product{border:1px solid var(--n503-line);border-radius:10px;overflow:hidden;background:#fff}.n503-product-image{height:265px;display:block;position:relative;background:#eee}.n503-product-image img{width:100%;height:100%;object-fit:cover}.n503-product-image>b{position:absolute;z-index:2;left:10px;top:10px;background:var(--n503-orange);color:#fff;border-radius:15px;padding:5px 10px}.n503-product>div{padding:10px}.n503-product h3{font-size:16px;line-height:1.3;min-height:42px;margin:0 0 8px}.n503-product p{color:#777;margin:0 0 10px}.n503-product p span{color:#ffb000}.n503-product strong{font-size:19px;color:var(--n503-red)}.n503-product del{color:#777;margin-left:5px;font-size:13px}.n503-product small{display:block;color:#45a56f;margin:10px 0 5px}.n503-progress{display:block;height:10px;border-radius:10px;background:#f8dfdb;overflow:hidden}.n503-progress i{display:block;width:55%;height:100%;background:#e73a4e}.n503-add{height:40px;margin-top:10px;border:1px solid var(--n503-green);color:var(--n503-green);border-radius:6px;display:flex;align-items:center;justify-content:center;gap:8px;font-weight:700}.n503-promos{padding-top:0}.n503-promos>.n503-container{display:grid;grid-template-columns:1fr 1fr;gap:14px}.n503-promos article{height:190px;position:relative;border-radius:10px;overflow:hidden}.n503-promos img{width:100%;height:100%;object-fit:cover}.n503-promos article div{position:absolute;inset:0;padding:30px;display:flex;flex-direction:column;color:var(--n503-green)}.n503-promos b{font:600 30px Lora,serif}.n503-flash>.n503-container{background:var(--n503-green);padding:26px 18px;border-radius:10px}.n503-flash header{display:flex;align-items:center;gap:8px;color:#fff}.n503-flash header strong,.n503-flash header h2{font:600 48px Lora,serif;margin:0}.n503-flash .n503-product-image{height:205px}.n503-kids header{display:flex;align-items:end;justify-content:space-between}.n503-kids header small{color:#888}.n503-kids header h2{margin:5px 0 20px}.n503-kids header a{font-weight:700;margin-bottom:24px}.n503-kids-cover{width:100%;height:380px;object-fit:cover;border-radius:10px;margin-bottom:10px}.n503-kids .n503-product-image{height:270px}.n503-season{padding-top:0}.n503-season>.n503-container{height:360px;position:relative;border-radius:10px;overflow:hidden}.n503-season img{width:100%;height:100%;object-fit:cover;filter:brightness(.86)}.n503-season div div{position:absolute;inset:0;width:44%;padding:50px;display:flex;flex-direction:column;justify-content:center;background:linear-gradient(90deg,#fff 20%,#ffffffdd 70%,transparent)}.n503-season h2{font:800 37px Manrope,sans-serif;text-transform:uppercase;color:#20314b}.n503-season p{font-size:20px}.n503-season a{align-self:flex-start;background:#20314b;color:#fff;border-radius:7px;padding:12px 30px}.n503-advice-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.n503-advice article img{width:100%;height:190px;object-fit:cover;border-radius:8px}.n503-advice h3{font:500 21px Lora,serif;margin:10px 0}.n503-advice p{color:#555;line-height:1.5;margin:0 0 12px}.n503-advice time{color:#888}.n503-footer-intro{background:var(--n503-green);color:#fff;text-align:center;padding:40px 0 20px}.n503-footer-intro h2,.n503-footer-intro h3{font:600 30px Lora,serif;color:var(--n503-mint)}.n503-footer-intro p{max-width:840px;margin:0 auto 22px;line-height:1.6}.n503-footer-intro div div{max-width:850px;margin:auto;background:var(--n503-dark);border-radius:8px;padding:14px;display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.n503-footer{background:var(--n503-green);color:#fff;padding:40px 0 15px}.n503-footer-grid{display:grid;grid-template-columns:1.15fr repeat(3,1fr);gap:45px}.n503-footer h3{font:600 20px Lora,serif;color:var(--n503-mint)}.n503-footer section{display:flex;flex-direction:column;gap:12px}.n503-footer p{margin:0;line-height:1.5}.n503-footer p i{width:24px}.n503-copyright{border-top:1px solid #ffffff33;margin-top:30px;padding-top:14px;text-align:center;color:#ffffffaa}
