@media(max-width:560px){.n503-container{width:min(100% - 22px,1180px)}.n503-head-actions button:nth-of-type(2){display:none}.n503-hero{height:440px}.n503-hero-slide>img{object-position:63% center}.n503-hero-copy{align-items:flex-start;text-align:left;justify-content:flex-start;padding-top:60px}.n503-hero-copy h1{font-size:42px}.n503-hero-copy p{max-width:230px}.n503-hero-tabs{display:none}.n503-section{padding:44px 0}.n503-section h2,.n503-categories h2{font-size:34px}.n503-tabs{overflow:auto}.n503-tabs button{min-width:120px}.n503-category-grid a{height:160px}.n503-product-image,.n503-kids .n503-product-image{height:180px}.n503-product h3{font-size:14px}.n503-product strong{font-size:16px}.n503-add{font-size:13px}.n503-promos article{height:155px}.n503-flash header{display:block}.n503-flash header strong,.n503-flash header h2{font-size:30px}.n503-kids header{align-items:start}.n503-kids header a{font-size:13px}.n503-kids-cover{height:220px}.n503-season>.n503-container{height:360px}.n503-season div div{width:100%;background:#ffffffb9}.n503-season h2{font-size:28px}.n503-advice-grid{grid-template-columns:1fr}.n503-advice article img{height:220px}.n503-footer-intro div div,.n503-footer-grid{grid-template-columns:1fr}.n503-footer-intro div div{text-align:left}.n503-head-actions{gap:5px}}
.n503-inner-hero{padding:62px 0;background:linear-gradient(135deg,#eef7f2,#f6f1eb)}.n503-inner-hero h1{margin:0;font:600 clamp(36px,5vw,58px) Lora,serif;color:var(--n503-green)}.n503-prose,.n503-form,.n503-news-list{width:min(900px,calc(100% - 32px));margin:45px auto;line-height:1.75}.n503-form{display:grid;gap:14px}.n503-form input,.n503-form textarea{width:100%;padding:13px;border:1px solid var(--n503-line);border-radius:7px}.n503-form button{justify-self:start;border:0;border-radius:7px;padding:12px 24px;background:var(--n503-green);color:#fff}.n503-news-list{display:grid;gap:18px}.n503-news-list article{padding:20px;border:1px solid var(--n503-line);border-radius:9px}.n503-news-list h2{margin:0 0 8px;font:600 26px Lora,serif}.n503-products-3{grid-template-columns:repeat(3,1fr)}@media(max-width:900px){.n503-products-3{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.n503-products-3{grid-template-columns:1fr}}
